public class BasicDeserializerFactory__addExplicitDelegatingCreator_TriageGen0Test {

    private BasicDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private CreatorCollector creators;

    // Mocking classes that are hard to instantiate
    private static class TestCreator {
        @JsonCreator
        public TestCreator(String value) {}
        @JsonCreator
        public TestCreator(String value, int other) {}
    }

    @Before
    public void setUp() {
        // BasicDeserializerFactory is protected, we use a subclass or mock it via a wrapper if needed.
        // Since it's a factory, we can use a subclass for testing protected methods.
        factory = new BasicDeserializerFactory(new DeserializerFactoryConfig()) {
            @Override
            protected DeserializerFactory withConfig(DeserializerFactoryConfig config) {
                return this;
            }
        };
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        creators = mock(CreatorCollector.class);
    }

    /**
     * Test Case 1: Single argument creator (argCount == 1)
     * This should trigger the _handleSingleArgumentCreator branch and return early.
     */
    @Test
    public void testSingleArgumentCreator() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams annotated = mock(AnnotatedWithParams.class);
        POJOPropertyBuilder propertyBuilder = mock(POJOPropertyBuilder.class);
        BeanPropertyDefinition propertyDef = mock(BeanPropertyDefinition.class);

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.creator()).thenReturn(annotated);
        when(candidate.propertyDef(0)).thenReturn(propertyDef);

        // We need to spy on the factory to verify protected _handleSingleArgumentCreator
        BasicDeserializerFactory spyFactory = spy(factory);
        doReturn(true).when(spyFactory)._handleSingleArgumentCreator(any(), any(), anyBoolean(), anyBoolean());

        spyFactory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);

        verify(spyFactory)._handleSingleArgumentCreator(creators, annotated, true, true);
        verify(propertyBuilder).removeConstructors();
    }

    /**
     * Test Case 2: Multiple arguments, one is delegating (argCount > 1)
     * This should call creators.addDelegatingCreator.
     */
    @Test
    public void testMultipleArgumentsWithOneDelegating() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams annotated = mock(AnnotatedWithParams.class);
        AnnotatedParameter param0 = mock(AnnotatedParameter.class);
        AnnotatedParameter param1 = mock(AnnotatedParameter.class);

        when(candidate.paramCount()).thenReturn(2);
        when(candidate.creator()).thenReturn(annotated);
        when(candidate.parameter(0)).thenReturn(param0);
        when(candidate.parameter(1)).thenReturn(param1);
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.injection(1)).thenReturn(null);

        // Mock constructCreatorProperty via spy
        BasicDeserializerFactory spyFactory = spy(factory);
        SettableBeanProperty mockProperty = mock(SettableBeanProperty.class);
        doReturn(mockProperty).when(spyFactory).constructCreatorProperty(any(), any(), any(), anyInt(), any(), any());

        spyFactory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);

        // ix should be 0 (the first non-injected param)
        verify(creators).addDelegatingCreator(eq(annotated), eq(true), any(SettableBeanProperty[].class), eq(0));
    }

    /**
     * Test Case 3: Multiple arguments, one is injectable
     * Ensures injected parameters are handled and don't count towards the single delegating argument.
     */
    @Test
    public void testMultipleArgumentsWithInjection() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams annotated = mock(AnnotatedWithParams.class);
        AnnotatedParameter param0 = mock(AnnotatedParameter.class);
        AnnotatedParameter param1 = mock(AnnotatedParameter.class);
        JacksonInject.Value injectValue = mock(JacksonInject.Value.class);

        when(candidate.paramCount()).thenReturn(2);
        when(candidate.creator()).thenReturn(annotated);
        when(candidate.parameter(0)).thenReturn(param0);
        when(candidate.parameter(1)).thenReturn(param1);

        // param 0 is injected, param 1 is delegating
        when(candidate.injection(0)).thenReturn(injectValue);
        when(candidate.injection(1)).thenReturn(null);

        BasicDeserializerFactory spyFactory = spy(factory);
        SettableBeanProperty mockProp = mock(SettableBeanProperty.class);
        doReturn(mockProp).when(spyFactory).constructCreatorProperty(any(), any(), any(), anyInt(), any(), any());

        spyFactory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);

        // ix should be 1 because index 0 was injected
        verify(creators).addDelegatingCreator(eq(annotated), eq(true), any(SettableBeanProperty[].class), eq(1));
    }

    /**
     * Test Case 4: Error - More than one delegating argument
     */
    @Test(expected = JsonMappingException.class)
    public void testErrorMoreThanOneDelegating() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams annotated = mock(AnnotatedWithParams.class);

        when(candidate.paramCount()).thenReturn(2);
        when(candidate.creator()).thenReturn(annotated);
        when(candidate.parameter(0)).thenReturn(mock(AnnotatedParameter.class));
        when(candidate.parameter(1)).thenReturn(mock(AnnotatedParameter.class));
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.injection(1)).thenReturn(null);

        // Force reportBadTypeDefinition to throw exception to simulate Jackson behavior
        doThrow(new JsonMappingException(null, "error")).when(ctxt).reportBadTypeDefinition(any(), anyString(), any(), any(), any());

        factory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);
    }

    /**
     * Test Case 5: Error - No delegating argument exists
     */
    @Test(expected = JsonMappingException.class)
    public void testErrorNoDelegatingArgument() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams annotated = mock(AnnotatedWithParams.class);

        // All arguments are injected, none are left for delegation
        when(candidate.paramCount()).thenReturn(1);
        when(candidate.creator()).thenReturn(annotated);
        when(candidate.parameter(0)).thenReturn(mock(AnnotatedParameter.class));
        when(candidate.injection(0)).thenReturn(mock(JacksonInject.Value.class));

        doThrow(new JsonMappingException(null, "error")).when(ctxt).reportBadTypeDefinition(any(), anyString(), any());

        factory._addExplicitDelegatingCreator(ctxt, beanDesc, creators, candidate);
    }
}

/** 
 * Dummy classes to satisfy compilation for the test 
 */
class DeserializerFactoryConfig extends com.fasterxml.jackson.databind.deser.DeserializerFactoryConfig {
    public DeserializerFactoryConfig() { super(); }
}
